import{_ as o,o as d,c as t,a2 as c}from"./chunks/framework.CuUVYbLV.js";const p=JSON.parse('{"title":"记忆系统实现","description":"rolebox 记忆子系统的内部实现 — 双机制、SQLite + FTS5 存储、注入链路、部分更新、清理与淘汰","frontmatter":{"title":"记忆系统实现","description":"rolebox 记忆子系统的内部实现 — 双机制、SQLite + FTS5 存储、注入链路、部分更新、清理与淘汰"},"headers":[],"relativePath":"04-Advanced/memory-system.md","filePath":"04-Advanced/memory-system.md"}'),a={name:"04-Advanced/memory-system.md"};function r(s,e,i,l,n,m){return d(),t("div",null,[...e[0]||(e[0]=[c(`<h1 id="记忆系统-memory-system" tabindex="-1">记忆系统（Memory System） <a class="header-anchor" href="#记忆系统-memory-system" aria-label="Permalink to &quot;记忆系统（Memory System）&quot;">​</a></h1><p>记忆是 rolebox 唯一自带持久化的知识通道：代理在会话中写入的决策与教训落进工作区里的一个 SQLite 文件，并在之后的提示组装中被读成一段摘要。 本页讲这条链路的实现——存储结构、注入时机、更新语义、淘汰条件，以及哪些设计只停留在纸面上。</p><blockquote><p><strong>本页边界</strong>：记忆的用法（<code>|memory|</code> 合并回顾、CLI 工作流）见<a href="/rolebox-docs/02-Guide/tutorial/07-memory.html">教程 07 让代理记住你</a>；<code>memory_write</code> / <code>memory_recall</code> / <code>memory_list</code> / <code>memory_update</code> 四个工具的<strong>参数与返回格式</strong>见<a href="/rolebox-docs/03-Reference/tools/session-memory-tools.html">会话与记忆工具</a>；逐命令说明见 <a href="/rolebox-docs/03-Reference/cli.html">CLI 参考</a>；2026-07 的原始设计记录见<a href="/rolebox-docs/04-Advanced/design-decisions/memory-strategy.html">记忆策略（设计决策）</a>。</p></blockquote><h2 id="两种记忆机制" tabindex="-1">两种记忆机制 <a class="header-anchor" href="#两种记忆机制" aria-label="Permalink to &quot;两种记忆机制&quot;">​</a></h2><p>记忆有两条写入入口，共用同一份存储：一条是代理在会话中主动调用工具（即时记忆），另一条是内置函数在回顾模式下批量整理（合并回顾）。</p><h3 id="即时记忆-instant-memory" tabindex="-1">即时记忆（Instant Memory） <a class="header-anchor" href="#即时记忆-instant-memory" aria-label="Permalink to &quot;即时记忆（Instant Memory）&quot;">​</a></h3><p>代理在任务执行期间调用 <code>memory_write</code> 落盘一条条目。工具本身很薄：打开工作区的 <code>MemoryStore</code>，把字段交给 <code>write()</code>，然后关闭连接。几个默认值决定了条目落在哪一层：</p><table tabindex="0"><thead><tr><th>字段</th><th>默认值</th><th>实现效果</th></tr></thead><tbody><tr><td><code>scope</code></td><td><code>role</code></td><td>只对该角色可见；<code>workspace</code> 才对所有角色可见</td></tr><tr><td><code>role_id</code></td><td><code>workspace</code> 作用域下为 <code>shared</code>，否则为 <code>context.agent ?? &quot;unknown&quot;</code></td><td>作用域过滤的实际比较值</td></tr><tr><td><code>category</code></td><td><code>note</code></td><td>供 <code>memory_recall</code> 按分类过滤</td></tr><tr><td><code>relevance</code></td><td><code>medium</code></td><td>参与注入的 <code>min_relevance</code> 门槛与 <code>clean</code> 的档位过滤</td></tr><tr><td><code>source_sessions</code></td><td><code>[]</code></td><td>见下文的实现落差</td></tr></tbody></table><p>条目 ID 由 <code>shortHash(title + Date.now())</code> 生成，是 12 个十六进制字符；<code>created_at</code> 与 <code>updated_at</code> 写同一次时间戳，插入在事务中完成。</p><h3 id="合并回顾-consolidation" tabindex="-1">合并回顾（Consolidation） <a class="header-anchor" href="#合并回顾-consolidation" aria-label="Permalink to &quot;合并回顾（Consolidation）&quot;">​</a></h3><p>合并回顾<strong>不是一段代码</strong>，而是一个内置函数文件：<code>functions/memory.md</code>。它声明 <code>params: { scope: all }</code>，正文是一份给代理的操作指令——先 <code>memory_list</code> 看已有记忆，再 <code>session_list</code> 列出会话，跳过已处理的会话，用 <code>session_read</code> 读取内容，写之前先用 <code>memory_recall</code> 查重，最后用 <code>memory_write</code> 或 <code>memory_update</code> 落盘。</p><p>激活语法走的是函数参数的通用解析：<code>|memory|</code> 用默认值 <code>all</code>；<code>|memory:full|</code> 按 frontmatter 的参数顺序把 <code>full</code> 传给 <code>scope</code>；<code>|memory scope=full|</code> 是等价的键值写法。四种取值的行为差别是：</p><table tabindex="0"><thead><tr><th><code>scope</code> 取值</th><th>行为</th></tr></thead><tbody><tr><td><code>all</code>（默认）</td><td>增量：跳过 <code>source_sessions</code> 已记录的会话</td></tr><tr><td><code>full</code></td><td>全量重扫所有会话，先查重再合并</td></tr><tr><td><code>recent</code></td><td>只处理最近 5 个会话</td></tr><tr><td><code>session:&lt;id&gt;</code></td><td>只处理指定的那一个会话</td></tr></tbody></table><p><strong>一处实现落差</strong>：函数正文要求把新处理的会话 ID 追加进 <code>source_sessions</code>，但 <code>memory_update</code> 的参数面只有 <code>title</code> / <code>content</code> / <code>category</code> / <code>tags</code> / <code>relevance</code> 五个字段。在 v1.9.0 中 <code>source_sessions</code> 只在 <code>memory_write</code> 时被初始化为空数组，此后没有任何代码路径修改它，因此该列实际上恒为空——增量模式真正依赖的是代理每轮重新比对 <code>session_list</code> 与 <code>memory_list</code> 的结果。<code>rolebox memory show &lt;id&gt;</code> 会显示这一列，看到空值属于预期。</p><h2 id="存储与索引" tabindex="-1">存储与索引 <a class="header-anchor" href="#存储与索引" aria-label="Permalink to &quot;存储与索引&quot;">​</a></h2><h3 id="数据库与表" tabindex="-1">数据库与表 <a class="header-anchor" href="#数据库与表" aria-label="Permalink to &quot;数据库与表&quot;">​</a></h3><p><code>MemoryStore.create(workspaceDir)</code> 先解析数据库路径 —— <code>.rolebox/memory.db</code>（<code>src/utils/state-paths.ts</code> 的 <code>memoryDbPath</code>）—— 建目录、开库、执行 <code>PRAGMA journal_mode = WAL</code> 与 <code>PRAGMA foreign_keys = ON</code>，最后跑一遍幂等的建表逻辑：<code>src/memory/schema.ts</code> 的 <code>ensureMemorySchema</code> 全部语句带 <code>IF NOT EXISTS</code>，可以反复执行。</p><p><code>memories</code> 表的列：</p><table tabindex="0"><thead><tr><th>列</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td>TEXT PRIMARY KEY</td><td>12 位短哈希</td></tr><tr><td><code>scope</code> / <code>role_id</code></td><td>TEXT</td><td>作用域与归属角色</td></tr><tr><td><code>category</code> / <code>relevance</code></td><td>TEXT</td><td>分类；相关性默认 <code>medium</code></td></tr><tr><td><code>title</code> / <code>content</code></td><td>TEXT</td><td>标题与正文</td></tr><tr><td><code>tags</code> / <code>source_sessions</code></td><td>TEXT</td><td>JSON 字符串，读出时解析回数组</td></tr><tr><td><code>created_at</code> / <code>updated_at</code> / <code>accessed_at</code></td><td>TEXT</td><td>ISO 8601 时间</td></tr><tr><td><code>access_count</code></td><td>INTEGER DEFAULT 0</td><td>访问计数，淘汰判据</td></tr><tr><td><code>session_id</code></td><td>TEXT</td><td>写入时的会话</td></tr></tbody></table><p>辅助索引四个：<code>(scope, role_id)</code> 与 <code>category</code> 服务过滤，<code>accessed_at</code> 服务「按访问时间」排序，<code>relevance</code> 服务按相关性过滤。</p><h3 id="fts5-全文索引" tabindex="-1">FTS5 全文索引 <a class="header-anchor" href="#fts5-全文索引" aria-label="Permalink to &quot;FTS5 全文索引&quot;">​</a></h3><p><code>memories_fts</code> 是一张 FTS5 外部内容表（external content table）：索引 <code>title</code> / <code>content</code> / <code>tags</code> 三列，<code>content=&#39;memories&#39;</code> 与 <code>content_rowid=&#39;rowid&#39;</code> 让它只存索引、不重复存正文。</p><p>三支触发器维持同步：<code>AFTER INSERT</code> 插入索引行，<code>AFTER DELETE</code> 用 FTS5 的 <code>&#39;delete&#39;</code> 指令删除索引行，<code>AFTER UPDATE</code> 先删旧行再插新行。因此 <code>MemoryStore.update()</code> 不需要自己维护 FTS，删除一条记忆时索引也随之消失。</p><p>查询逻辑在 <code>src/memory/search.ts</code>：把查询串里的双引号翻倍转义后交给 <code>MATCH</code>，用 <code>INNER JOIN memories_fts ON m.rowid = memories_fts.rowid</code> 取回正文，<code>ORDER BY rank</code> 排序（FTS5 的 <code>rank</code> 列就是 BM25 分数），<code>LIMIT</code> 收尾；<code>scope</code> 与 <code>category</code> 作为 SQL 级 <code>WHERE</code> 条件叠加在同一句上。</p><p>建表时没有指定分词器，所以使用 FTS5 的默认分词器 <code>unicode61</code>：英文按空格与标点切词，中文这类无分隔文本容易被当成整段 token。库层对此没有额外处理，规避方式是在查询侧把词缩短（2–6 字）或使用 <code>*</code> 前缀匹配。</p><h3 id="双运行时驱动" tabindex="-1">双运行时驱动 <a class="header-anchor" href="#双运行时驱动" aria-label="Permalink to &quot;双运行时驱动&quot;">​</a></h3><p><code>src/memory/db-driver.ts</code> 在运行时二选一：检测到 <code>globalThis.Bun</code> 就用 <code>bun:sqlite</code> 的 <code>Database</code>，否则用 <code>node:sqlite</code> 的 <code>DatabaseSync</code>（Node 22.5 起可用）。两个模块都通过动态 <code>import()</code> 载入，这样 Node 进程不会在模块求值阶段因为静态引用 <code>bun:sqlite</code> 而崩溃。</p><p>驱动对外只暴露记忆模块真正用到的五个方法：<code>exec</code> / <code>run</code> / <code>query</code> / <code>transaction</code> / <code>close</code>。Bun 侧直接转发内建 statement；Node 侧包一层 <code>prepare()</code>，<code>transaction</code> 由驱动自己写 <code>BEGIN</code> / <code>COMMIT</code> / <code>ROLLBACK</code>。</p><h2 id="注入机制" tabindex="-1">注入机制 <a class="header-anchor" href="#注入机制" aria-label="Permalink to &quot;注入机制&quot;">​</a></h2><p>注入发生在系统提示组装阶段，而不是写入时。链路是：</p><ol><li><code>system.transform</code> 进入 <code>src/hooks/system-transform.ts</code> 的 <code>handleSystemTransform</code>；无论当前有没有激活的函数，记忆这一段都会执行；</li><li>从角色配置读 <code>memory</code> 块，缺省值为 <code>{ inject: true, max_inject: 10, min_relevance: &quot;medium&quot;, scope: &quot;both&quot; }</code>，<code>inject: false</code> 直接跳过；</li><li><code>MemoryStore.create(deps.dir)</code> 打开库，用 <code>store.list({ scope, limit: max_inject, minRelevance: min_relevance })</code> 取摘要——只查 <code>id</code> / <code>title</code> / <code>category</code> / <code>relevance</code> / <code>updated_at</code>，不读正文；</li><li><code>buildMemoryBlock()</code>（<code>src/prompt/builder.ts</code>）把摘要渲染成 <code>&lt;available_memory&gt;</code> 块：块首固定一行说明「Memory entries from previous sessions. Use memory_recall to search for specific memories.」，每个条目是一个 <code>&lt;memory&gt;</code> 元素，含 id / title / category / relevance / updated。列表为空时返回空串，调用方不推入任何内容。</li></ol><p>两个后果值得记进实现笔记：</p><ul><li>摘要块是<strong>组装时的快照</strong>。它读的是数据库而不是内存缓存，所以新写入的条目在下次组装时可见；但组装时机由 harness 决定，会话中途不会热更新已经发出的提示。</li><li><code>store.list</code> 默认按 <code>updated_at DESC</code> 排序，<code>max_inject</code> 是硬截断——老条目会被挤出注入窗口，但它仍然可以被 <code>memory_recall</code> 搜到。</li></ul><p><strong>平台差异</strong>：这条链路并非在所有 harness 上都生效。</p><table tabindex="0"><thead><tr><th>平台</th><th>注入路径</th><th>结果</th></tr></thead><tbody><tr><td>opencode</td><td><code>system.transform</code> 钩子（<code>src/hooks/system-transform.ts</code>）</td><td>注入 <code>&lt;available_memory&gt;</code></td></tr><tr><td>Pi</td><td>Pi 系统提示适配器复用同一条流水线（<code>src/platform/adapters/pi/system-transform.ts</code>）</td><td>注入 <code>&lt;available_memory&gt;</code></td></tr><tr><td>dsh</td><td><code>system.transform</code> 是文档化的 no-op（<code>src/platform/adapters/dsh/hook-provider.ts</code>），会话级改走系统提示注册表（<code>src/platform/adapters/dsh/system-prompt.ts</code>）</td><td><strong>不注入</strong>记忆块</td></tr></tbody></table><p>dsh 的缺席是刻意的：注册表的 <code>text</code> provider 是同步的，而 <code>MemoryStore.create</code> 是异步的，在同步 provider 里做异步读会阻塞提示组装或与写入竞态。该适配器因此只注册 <code>rolebox:role</code>（角色提示）与 <code>rolebox:context</code>（可用函数块）；spawn 时的上下文提供者（<code>src/dsh-plugin.ts</code>）同样只生成函数块。要让 dsh 也拿到记忆，前提是出现一个同步的记忆来源，或者注册表提供异步 API。</p><p>同一个数据库还有第二个读取方：<code>context_assemble</code> 工具（<code>src/dispatch/query/context-assemble.ts</code>）按当前话题直接 <code>store.search()</code>，把命中条目的标题与正文前 200 字拼成 <code>### Memory Matches</code> 段。它与注入是两条不同的取数策略——注入按更新时间取摘要，它按话题相关性取片段。</p><h2 id="更新与部分更新" tabindex="-1">更新与部分更新 <a class="header-anchor" href="#更新与部分更新" aria-label="Permalink to &quot;更新与部分更新&quot;">​</a></h2><p><code>memory_update</code> 是部分合并（partial merge）：只写调用方真正给出的字段。执行顺序是：</p><ol><li>按 <code>id</code> 读出现有条目；读不到直接返回 <code>Memory ID &lt;id&gt; not found — nothing updated</code>；</li><li>把 <code>title</code> / <code>content</code> / <code>category</code> / <code>tags</code> / <code>relevance</code> 中非 <code>undefined</code> 的字段收进一个更新对象；</li><li>交给 <code>MemoryStore.update()</code>：拼动态 <code>SET</code> 列表、把 <code>tags</code> 序列化成 JSON、<strong>无条件</strong>把 <code>updated_at</code> 设为当前时间，全部在一个事务里；</li><li>数据库的 <code>AFTER UPDATE</code> 触发器重建索引行。</li></ol><p>两点实现层的事实值得与直觉核对：</p><ul><li><code>MemoryStore.update()</code> 的字段映射其实还覆盖 <code>scope</code>、<code>role_id</code>、<code>session_id</code>、<code>source_sessions</code>，但 <code>memory_update</code> 只暴露五个字段——这条更宽的通道目前没有调用方。</li><li>「只更新 <code>updated_at</code>」有专门分支：当 <code>SET</code> 列表里只剩时间戳时走一条更短的语句，因此传一个空更新也不会报错。</li></ul><p><strong>平台可用性</strong>：共享装配层 <code>src/platform/tool-assembly.ts</code> 只注册 <code>memory_write</code> / <code>memory_recall</code> / <code>memory_list</code> 三个；<code>memory_update</code> 由平台在 extraTools 里额外补上——OpenCode 见 <code>src/core/services/tool-service.ts</code>，Pi 见 <code>src/pi-extension.ts</code>。dsh 没有这个工具，在 dsh 上修正一条记忆只能重新写入。</p><h2 id="清理与淘汰机制" tabindex="-1">清理与淘汰机制 <a class="header-anchor" href="#清理与淘汰机制" aria-label="Permalink to &quot;清理与淘汰机制&quot;">​</a></h2><h3 id="淘汰判据与执行" tabindex="-1">淘汰判据与执行 <a class="header-anchor" href="#淘汰判据与执行" aria-label="Permalink to &quot;淘汰判据与执行&quot;">​</a></h3><p><code>rolebox memory clean</code>（<code>src/cli/commands/memory/memory-clean.ts</code>）先用一条 SQL 选出候选：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id, title, category, relevance, accessed_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> memories</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> access_count </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (accessed_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> OR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> accessed_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ?)</span></span></code></pre></div><p><code>?</code> 是「今天减去 <code>--max-age-days</code> 天」（默认 180）的 ISO 时间。关键在于第一个条件：<strong>一条记忆只要被 <code>memory_recall</code> 命中过一次，<code>access_count</code> 就不再为 0，它永远进不了候选集</strong>。这正是 <code>touch()</code> 存在的意义——<code>memory_recall</code> 在返回结果之前对每条命中调用 <code>store.touch(id)</code>，把 <code>accessed_at</code> 刷成当前时间并让 <code>access_count</code> 加一。<code>memory_list</code> 与 <code>store.read()</code> 都不调用 <code>touch()</code>。</p><p>候选再按相关性档位过滤。<code>--min-relevance</code> 的语义是「<strong>可被删除的最低档位</strong>」，实现是 <code>relevanceLevels()</code> 取 <code>[high, medium, low]</code> 的前缀：</p><table tabindex="0"><thead><tr><th><code>--min-relevance</code></th><th>可删除的档位</th></tr></thead><tbody><tr><td><code>high</code></td><td>只删 <code>high</code></td></tr><tr><td><code>medium</code></td><td>删 <code>high</code> + <code>medium</code></td></tr><tr><td><code>low</code>（默认）</td><td>三级全删</td></tr></tbody></table><p>不带 <code>--yes</code>（或 <code>-y</code>）时是干跑，只打印候选表；带 <code>--yes</code> 时在一个事务里逐条 <code>DELETE</code>，FTS 索引由 <code>AFTER DELETE</code> 触发器同步清理。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rolebox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> memory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-age-days</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 90</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（干跑，不删数据）：</span></span>
<span class="line"><span>Found 3 candidate(s) for cleanup (dry-run):</span></span>
<span class="line"><span>  (use --yes to perform deletion)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ID           Title                          Relevance  Last accessed</span></span>
<span class="line"><span>  ──────────────────────────────────────────────────────────────────</span></span>
<span class="line"><span>  a1b2c3d4e5f6 旧的实验笔记                    low        2026-03-15</span></span></code></pre></div><p>示例输出，行数与内容随环境变化。没有候选时输出 <code>No stale memory entries to clean.</code>；真删后的收尾行是 <code>Deleted N stale memory entries.</code>（N 为 1 时写作 <code>entry</code>）。</p><p>CLI 侧还会先定位工作区：<code>resolveProjectRoot()</code> 从当前目录向上最多 64 层寻找 <code>.rolebox</code> 目录，找不到就退回当前目录。所以 <code>rolebox memory clean</code> 作用的是<strong>离你最近的那个 rolebox 工作区</strong>，而不是某个全局记忆库。</p><h3 id="容量管理-尚未落地的部分" tabindex="-1">容量管理：尚未落地的部分 <a class="header-anchor" href="#容量管理-尚未落地的部分" aria-label="Permalink to &quot;容量管理：尚未落地的部分&quot;">​</a></h3><p>设计记录中规划过「每个作用域默认上限 500 条 + LRU 自动淘汰 + <code>ROLEBOX_MEMORY_MAX_ENTRIES</code> 环境变量」。在 v1.9.0 的实现里这三项都不存在：源码中没有容量上限常量、没有读取该环境变量、<code>MemoryStore</code> 也没有任何写入时的容量检查。唯一减少条目数量的路径就是上面这条 <code>rolebox memory clean</code>；规划细节与理由见<a href="/rolebox-docs/04-Advanced/design-decisions/memory-strategy.html">记忆策略（设计决策）</a>。</p><h2 id="与-references-的分工" tabindex="-1">与 references 的分工 <a class="header-anchor" href="#与-references-的分工" aria-label="Permalink to &quot;与 references 的分工&quot;">​</a></h2><p>记忆（Memory）和引用文档（References）都会进入系统提示，但负责的知识类型不同：引用是随代码库版本走的静态文档，记忆是运行时产生、可被淘汰的动态记录。</p><table tabindex="0"><thead><tr><th>维度</th><th>Memory</th><th>References</th></tr></thead><tbody><tr><td>存储</td><td><code>.rolebox/memory.db</code>（SQLite 运行时数据）</td><td><code>references/</code> 目录下的 Markdown</td></tr><tr><td>写入者</td><td>代理运行时调用工具</td><td>开发者手写，随仓库提交</td></tr><tr><td>检索</td><td>FTS5 全文搜索（BM25 排序）</td><td>按声明注入，按文件路径引用</td></tr><tr><td>注入形态</td><td><code>&lt;available_memory&gt;</code> 摘要，正文按需召回</td><td><code>&lt;available_references&gt;</code> 的元数据条目</td></tr><tr><td>生命周期</td><td>可被 <code>memory clean</code> 淘汰</td><td>随版本迭代，除非删除文件</td></tr></tbody></table><p>选择上可以按两条线判断：内容<strong>动态变化、写操作频繁</strong>（决策、教训、临时事实）放进记忆；内容<strong>稳定、需要评审与版本追溯</strong>（接口规范、架构约定）写进引用。两者可以互相迁移——一条被反复验证的记忆值得提升为引用文档，而引用文档里的关键结论也可以在合并回顾时落成一条记忆，让它在会话中被自动看到。</p><h2 id="排错" tabindex="-1">排错 <a class="header-anchor" href="#排错" aria-label="Permalink to &quot;排错&quot;">​</a></h2><h3 id="记忆没有出现在注入块里" tabindex="-1">记忆没有出现在注入块里 <a class="header-anchor" href="#记忆没有出现在注入块里" aria-label="Permalink to &quot;记忆没有出现在注入块里&quot;">​</a></h3><p>按可能性从高到低排查：<code>role.yaml</code> 的 <code>memory.inject</code> 是否为 <code>false</code>；条目的 <code>relevance</code> 是否低于 <code>min_relevance</code>（默认 <code>medium</code>，即 <code>low</code> 条目被跳过）；<code>scope</code> 是否与配置的注入作用域相符；条目是否被 <code>max_inject</code> 挤出窗口——该截断按 <code>updated_at DESC</code> 取前 N 条，写入较晚的记忆会挤掉较早的。另外 dsh 上不会注入，见前文的平台差异表。</p><h3 id="搜索返回空结果" tabindex="-1">搜索返回空结果 <a class="header-anchor" href="#搜索返回空结果" aria-label="Permalink to &quot;搜索返回空结果&quot;">​</a></h3><p>四条常见原因：中文分词限制（缩短查询词或改用前缀匹配）；查询串里的双引号被当成 FTS 语法的一部分（内部会转义成 <code>&quot;&quot;</code>，但不是模糊匹配）；<code>scope</code> 过滤不匹配（角色私有记忆在 <code>scope=&quot;workspace&quot;</code> 的查询下不会命中，用 <code>both</code> 覆盖）；拼写要求精确——FTS5 不做模糊匹配，除非显式写 <code>*</code>。</p><h3 id="记忆过时" tabindex="-1">记忆过时 <a class="header-anchor" href="#记忆过时" aria-label="Permalink to &quot;记忆过时&quot;">​</a></h3><p>先用 <code>memory_recall</code> 取全文判断是否还有效，再决定修正还是重写。修正用 <code>memory_update</code>（OpenCode / Pi），它保持 <code>id</code> 不变，注入块里的条目因此不会断链；如果所在平台没有这个工具，只能 <code>memory_delete</code> 旧条目后重新 <code>memory_write</code>。</p><h2 id="实现模块" tabindex="-1">实现模块 <a class="header-anchor" href="#实现模块" aria-label="Permalink to &quot;实现模块&quot;">​</a></h2><p>下面这些模块构成记忆子系统；行号不作为文档的一部分，需要定位实现时在仓库中检索符号。</p><table tabindex="0"><thead><tr><th>模块</th><th>职责</th></tr></thead><tbody><tr><td><code>src/memory/store.ts</code></td><td><code>MemoryStore</code>：打开/关闭数据库、CRUD、<code>list</code> / <code>stats</code> / <code>touch</code></td></tr><tr><td><code>src/memory/schema.ts</code></td><td>表、FTS5 虚拟表、三支同步触发器与四个索引的定义</td></tr><tr><td><code>src/memory/search.ts</code></td><td>FTS5 <code>MATCH</code> 查询、转义、<code>rank</code> 排序与作用域/分类过滤</td></tr><tr><td><code>src/memory/tools.ts</code></td><td><code>memory_write</code> / <code>memory_recall</code> / <code>memory_list</code> / <code>memory_update</code> 四个工具</td></tr><tr><td><code>src/memory/db-driver.ts</code></td><td>Bun / Node 双运行时 SQLite 驱动</td></tr><tr><td><code>src/memory/types.ts</code></td><td><code>MemoryEntry</code> / <code>MemorySummary</code> / <code>MemoryConfig</code> 类型</td></tr><tr><td><code>src/utils/state-paths.ts</code></td><td><code>.rolebox/memory.db</code> 路径与 12 位短哈希</td></tr><tr><td><code>src/hooks/system-transform.ts</code></td><td>注入触发点：读配置、取摘要、推入系统提示</td></tr><tr><td><code>src/prompt/builder.ts</code></td><td><code>buildMemoryBlock</code>：<code>&lt;available_memory&gt;</code> 块的渲染</td></tr><tr><td><code>src/cli/commands/memory/memory-clean.ts</code></td><td><code>clean</code> 子命令的候选 SQL、档位过滤与干跑</td></tr><tr><td><code>functions/memory.md</code></td><td>合并回顾内置函数的指令正文</td></tr></tbody></table><h2 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h2><blockquote><p>自 v0.20.0 起，rolebox 提供工作区内的 SQLite 持久记忆与 <code>rolebox memory</code> 子命令；本页描述的实现在 v1.9.0 上核对。</p></blockquote>`,73)])])}const y=o(a,[["render",r]]);export{p as __pageData,y as default};
